using System.Collections.ObjectModel;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
namespace AnoWowItemEditor;

internal sealed record CreatedSetPiece(int ExistingId,CatalogItem Item,CloneBlueprint? Addition,DropPlan? Drops=null)
{
    public string Name=>Item.Name;
    public string Subtype=>Item.SubtypeName;
    public string Status=>ExistingId>0?"Saved member":"New duplicate on save";
    public int Level=>Item.ItemLevel;
}
internal sealed class CreatedSetsWindow : Window
{
    private CatalogResult catalog;
    private ReferenceCatalog refs;
    private CreatedSetSession? session;
    private readonly ComboBox sets=new(){DisplayMemberPath="Label",MinWidth=300};
    private readonly TextBox name=new(){Width=330},search=new(){Width=280};
    private readonly ItemKindFilter kinds;
    private readonly ComboBox slot=new(){DisplayMemberPath="Label",Width=180};
    private readonly ObservableCollection<CreatedSetPiece> draft=[];
    private readonly DataGrid members=DesignerWindow.Table(("Member","Name"),("Type","Subtype"),("iLvl","Level"),("State","Status")),bases=DesignerWindow.Table(("Base item","Name"),("Type","SubtypeName"),("iLvl","ItemLevel"));
    private readonly TextBlock feedback=DesignerWindow.Text("Choose a created set to modify.",12);
    private readonly Button save=new(){Content="Review & save membership",IsEnabled=false};
    private readonly DockPanel body=new(){ClipToBounds=true};
    private readonly EquipmentSetView equipment=new();
    private readonly TabControl views=new();
    private bool busy,loading;
    private readonly int? initialSetId;
    internal bool Saved {get;private set;}
    internal bool FooterVisible=>save.TransformToAncestor((FrameworkElement)Content).TransformBounds(new Rect(save.RenderSize)).Bottom<=((FrameworkElement)Content).ActualHeight;
    internal CreatedSetsWindow(CatalogResult catalog,ReferenceCatalog refs,CreatedSetSession? verification=null,int? initialSetId=null)
    {
        this.catalog=catalog;this.refs=refs;this.initialSetId=initialSetId;kinds=new(catalog.Tooltips,true);Title="Modify created sets";Width=1450;Height=880;MinWidth=1100;MinHeight=700;Background=new SolidColorBrush(Color.FromRgb(35,36,40));WindowStartupLocation=WindowStartupLocation.CenterOwner;
        var root=new DockPanel{Margin=new Thickness(20),Background=Background};Content=root;var heading=DesignerWindow.Text("MODIFY CREATED SETS",23);heading.Foreground=Brushes.LightSkyBlue;DockPanel.SetDock(heading,Dock.Top);root.Children.Add(heading);
        var top=new WrapPanel{Margin=new Thickness(0,12,0,12)};DockPanel.SetDock(top,Dock.Top);root.Children.Add(top);top.Children.Add(sets);name.Margin=new Thickness(12,0,12,0);name.ToolTip="Set name";top.Children.Add(name);DesignerWindow.Button("Reload set",top).Click+=async(_,_)=>{if(ConfirmDiscard())await Select();};
        var note=DesignerWindow.Text("Remove detaches a saved piece from this set; the item and its drops remain available. Add creates a new duplicate of the selected base, with default 0.01% world drops. Double-click new copies to edit their draft. Save membership before editing saved items, bonuses or drops.",12);DockPanel.SetDock(note,Dock.Top);note.Margin=new Thickness(0,0,0,12);root.Children.Add(note);
        DockPanel.SetDock(feedback,Dock.Bottom);root.Children.Add(feedback);var bottom=new WrapPanel{Margin=new Thickness(0,12,0,12)};DockPanel.SetDock(bottom,Dock.Bottom);root.Children.Add(bottom);bottom.Children.Add(save);DesignerWindow.Button("Set testing checklist…",bottom).Click+=async(_,_)=>{if(session is null||busy||!CanOpenEditor())return;await Run(async()=>{var review=new SetChecklistWindow(catalog,session.Id){Owner=this};review.ShowDialog();if(review.Saved){Saved=true;catalog=review.Catalog;refs=review.References??refs;await LoadSelected();Filter();}});};DesignerWindow.Button("Character preview & balance…",bottom).Click+=async(_,_)=>{if(session is null||busy||!CanOpenEditor())return;await Run(async()=>{var preview=new SetAnalysisWindow(catalog,session.Id){Owner=this};preview.ShowDialog();if(preview.Saved){Saved=true;catalog=preview.CatalogSnapshot;refs=await ReferenceCatalog.LoadAsync();await LoadSelected();Filter();}});};DesignerWindow.Button("Edit selected saved item…",bottom).Click+=async(_,_)=>await Edit(false);DesignerWindow.Button("Edit set bonuses…",bottom).Click+=async(_,_)=>await Edit(true);DesignerWindow.Button("Edit selected item drops…",bottom).Click+=async(_,_)=>await EditDrops();
        root.Children.Add(body);var grid=new Grid();grid.ColumnDefinitions.Add(new());grid.ColumnDefinitions.Add(new(){Width=new GridLength(16)});grid.ColumnDefinitions.Add(new());body.Children.Add(views);views.Items.Add(new TabItem{Header="Equipment layout",Content=equipment});views.Items.Add(new TabItem{Header="Members & add copies",Content=grid});equipment.SelectionChanged+=row=>{if(row?.Key is CreatedSetPiece piece)members.SelectedItem=piece;};equipment.EditRequested+=async row=>{if(row.Key is CreatedSetPiece piece){members.SelectedItem=piece;await Edit(false);}};equipment.DropRequested+=async row=>{if(row.Key is CreatedSetPiece piece){members.SelectedItem=piece;await EditDrops();}};equipment.EmptySlotSelected+=target=>{slot.SelectedItem=slot.Items.Cast<FilterChoice>().FirstOrDefault(c=>c.Id==target)??slot.Items[0];views.SelectedIndex=1;};members.SelectionChanged+=(_,_)=>{if(members.SelectedItem is CreatedSetPiece piece&&!Equals(equipment.Selection?.Key,piece))equipment.SelectKey(piece);};members.MouseDoubleClick+=async(_,_)=>await Edit(false);
        var left=new DockPanel();grid.Children.Add(left);var remove=new Button{Content="Remove selected member from draft",Margin=new Thickness(0,0,0,10)};DockPanel.SetDock(remove,Dock.Top);left.Children.Add(remove);remove.Click+=(_,_)=>{if(members.SelectedItem is CreatedSetPiece row){draft.Remove(row);Update();}};members.ItemsSource=draft;left.Children.Add(members);
        var right=new DockPanel();Grid.SetColumn(right,2);grid.Children.Add(right);var filters=new WrapPanel{Margin=new Thickness(0,0,0,10)};DockPanel.SetDock(filters,Dock.Top);right.Children.Add(filters);search.ToolTip="Find base item by name or ID";filters.Children.Add(search);slot.Margin=new Thickness(10,0,0,0);filters.Children.Add(slot);filters.Children.Add(kinds);var add=new Button{Content="Add selected base as a new copy",Margin=new Thickness(0,0,0,10)};DockPanel.SetDock(add,Dock.Top);right.Children.Add(add);right.Children.Add(bases);add.Click+=async(_,_)=>{if(bases.SelectedItem is CatalogItem item&&session is not null)await Run(async()=>{var source=await ItemCloning.LoadAsync(item.Id);var copyDraft=new CatalogItem(new(source.Item.Current.Fields,StringComparer.OrdinalIgnoreCase){["ItemSet"]=session.Id.ToString()});var piece=new CreatedSetPiece(0,copyDraft,source);draft.Add(piece);Update();equipment.SelectKey(piece);views.SelectedIndex=0;feedback.Text="New copy added to draft. Its source remains unchanged.";});};
        slot.ItemsSource=new[]{new FilterChoice(-1,"All equipment slots")}.Concat(GearDesign.EquipmentSlots.Where(p=>p.Key is not (3 or 18)).Select(p=>new FilterChoice(p.Key,p.Value))).ToArray();slot.SelectedIndex=0;search.TextChanged+=(_,_)=>Filter();slot.SelectionChanged+=(_,_)=>Filter();kinds.Changed+=Filter;name.TextChanged+=(_,_)=>Update();sets.SelectionChanged+=async(_,_)=>{if(loading)return;if(!ConfirmDiscard()){loading=true;sets.SelectedItem=sets.Items.Cast<ContentChoice>().FirstOrDefault(s=>s.Id==session?.Id);loading=false;return;}await Select();};save.Click+=async(_,_)=>await Save();Loaded+=async(_,_)=>{if(verification is null)await LoadList();else{loading=true;sets.ItemsSource=new[]{new ContentChoice(verification.Id,verification.Name)};sets.SelectedIndex=0;loading=false;session=verification;foreach(var item in session.Members.Values)draft.Add(new(item.Item.Current.Id,item.Item.Current,null));name.Text=session.Name;Update();}};Closing+=(_,e)=>{if(busy||!ConfirmDiscard())e.Cancel=true;};Filter();
    }
    private bool Dirty=>session is not null&&(name.Text.Trim()!=session.Name||draft.Any(p=>p.ExistingId==0)||!draft.Where(p=>p.ExistingId>0).Select(p=>p.ExistingId).Order().SequenceEqual(session.Members.Keys.Order()));
    private bool ConfirmDiscard()=>!Dirty||MessageBox.Show(this,"Discard unsaved membership changes?","Unsaved set draft",MessageBoxButton.YesNo,MessageBoxImage.Question)==MessageBoxResult.Yes;
    private async Task Run(Func<Task> work){if(busy)return;busy=true;body.IsEnabled=sets.IsEnabled=save.IsEnabled=false;try{await work();}catch(Exception ex){feedback.Text=ex.Message;}finally{busy=false;body.IsEnabled=sets.IsEnabled=true;Update();}}
    private async Task LoadList(){await Run(async()=>{loading=true;sets.ItemsSource=(await ContentEditing.ListAsync()).Where(o=>o.Kind=="NewSet"&&o.Active&&catalog.Tooltips.Sets.ContainsKey(o.EntityId)).Select(o=>new ContentChoice(o.EntityId,catalog.Tooltips.Sets[o.EntityId].Name)).DistinctBy(s=>s.Id).ToArray();loading=false;if(sets.Items.Count>0){loading=true;sets.SelectedItem=sets.Items.Cast<ContentChoice>().FirstOrDefault(s=>s.Id==initialSetId)??sets.Items[0];loading=false;await LoadSelected();}else feedback.Text="No active created sets found. Create a set first.";});}
    private async Task Select()=>await Run(LoadSelected);
    private async Task LoadSelected(){if(sets.SelectedItem is not ContentChoice selected)return;var previous=session;var selectedItem=(members.SelectedItem as CreatedSetPiece)?.ExistingId;feedback.Text="Refreshing selected set…";session=await CreatedSets.Load(selected.Id,previous);catalog=SetCatalogRefresh.CreatedSet(catalog,session,previous,refs);draft.Clear();name.Clear();foreach(var item in session.Members.Values)draft.Add(new(item.Item.Current.Id,item.Item.Current,null));name.Text=session.Name;Update();if(selectedItem is >0)equipment.SelectKey(draft.FirstOrDefault(p=>p.ExistingId==selectedItem));feedback.Text=$"Set {session.Id} · {draft.Count} members. Changes are drafts until reviewed and saved.";}
    private void Filter(){int target=(slot.SelectedItem as FilterChoice)?.Id??-1;string q=search.Text.Trim();bases.ItemsSource=catalog.Items.Where(i=>i.Slot is not (0 or 4 or 19)&&GearDesign.Targets(i).Any()&&(target<0||GearDesign.Targets(i).Contains(target))&&kinds.Matches(i)&&(q.Length==0||i.Id.ToString()==q||i.Name.Contains(q,StringComparison.OrdinalIgnoreCase))).ToArray();}
    private void Update(){save.IsEnabled=!busy&&Dirty;equipment.Bind(draft.Select(p=>new EquipmentViewItem(p,p.Item)),catalog.Tooltips,catalog.Items.ToDictionary(i=>i.Id));}
    private async Task Save(){if(session is null||busy)return;await Run(async()=>{var additions=draft.Where(p=>p.ExistingId==0).Select(p=>p.Addition!).ToArray();var additionDrafts=draft.Where(p=>p.ExistingId==0).Select(p=>p.Item).ToArray();var world=additions.Length>0?await WorldDropCatalog.LoadAsync():null;var plans=draft.Where(p=>p.ExistingId==0).Select(p=>WorldDrops.Replan(world!,p.Item,p.Drops??world!.Plan(p.Item,0.01m))).ToArray();if(plans.Any(p=>p.Targets.Count==0))throw new InvalidOperationException("A new copy has no eligible world-drop targets. Choose a supported base item.");if(draft.Count is <2 or >17)throw new InvalidOperationException("Choose 2–17 members.");string summary=$"Name: {name.Text.Trim()}\nMembers retained: {string.Join(", ",draft.Where(p=>p.ExistingId>0).Select(p=>p.Name))}\nRemoved (items preserved): {string.Join(", ",session.Members.Where(p=>draft.All(d=>d.ExistingId!=p.Key)).Select(p=>p.Value.Item.Current.Name))}\nNew duplicates: {string.Join(", ",draft.Where(p=>p.ExistingId==0).Select(p=>p.Name))}\nNew copies use the reviewed drop locations below. Selected bosses replace world drops for that copy."+"\n\n"+string.Join("\n",additionDrafts.Select((p,n)=>p.Name+": "+plans[n].Summary));var review=new ContentReviewWindow("created set membership",session.Name,string.Join("\n",session.Members.Values.Select(p=>p.Item.Current.Name)),summary){Owner=this};if(review.ShowDialog()!=true)return;await CreatedSets.Save(session,name.Text.Trim(),draft.Where(p=>p.ExistingId>0).Select(p=>p.ExistingId).ToArray(),additions,plans,additionDrafts);Saved=true;await LoadSelected();Filter();feedback.Text="Saved with revert/reapply history. Reload the server to use the changed set.";});}
    private bool CanOpenEditor(){if(!Dirty)return true;feedback.Text="Review and save membership changes first, or reload the set to discard them.";return false;}
    private async Task Edit(bool bonus){if(session is null||busy)return;if(!bonus&&members.SelectedItem is CreatedSetPiece pending&&pending.ExistingId==0){await Run(()=>{var editor=new ItemEditorWindow(catalog,pending.Addition!.Item.Current.Id,draft:pending.Item){Owner=this};if(editor.ShowDialog()==true&&editor.AcceptedDraft is {} edited){var updated=pending with{Item=edited};draft[draft.IndexOf(pending)]=updated;Update();equipment.SelectKey(updated);}return Task.CompletedTask;});return;}if(!CanOpenEditor())return;await Run(async()=>{if(bonus){var editor=new ContentEditorWindow("Set",catalog,refs,session.Id){Owner=this};editor.ShowDialog();if(!editor.Saved)return;Saved=true;refs=await ReferenceCatalog.LoadAsync();foreach(var p in refs.Data.Spells)catalog.Tooltips.Spells[p.Key]=p.Value;foreach(var p in refs.Data.Effects)catalog.Tooltips.Effects[p.Key]=p.Value;foreach(var p in refs.Data.Misc)catalog.Tooltips.Misc[p.Key]=p.Value;foreach(var p in refs.Data.Durations)catalog.Tooltips.Durations[p.Key]=p.Value;}else if(members.SelectedItem is CreatedSetPiece row&&row.ExistingId>0){var editor=new ItemEditorWindow(catalog,row.ExistingId){Owner=this};editor.ShowDialog();if(!editor.Saved)return;Saved=true;var additionalItems=new List<CatalogItem>();foreach(int id in editor.SavedItemIds.Where(id=>!session.Members.ContainsKey(id)))additionalItems.Add((await ItemEditing.LoadAsync(id)).Current);if(additionalItems.Count>0)catalog=SetCatalogRefresh.Items(catalog,additionalItems);}else return;await LoadSelected();Filter();});}
    private async Task EditDrops(){if(session is null||busy||members.SelectedItem is not CreatedSetPiece row)return;if(row.ExistingId==0){await Run(async()=>{var world=await WorldDropCatalog.LoadAsync();var editor=new DropLocationWindow(row.Item,row.Drops??world.Plan(row.Item,0.01m),world){Owner=this};if(editor.ShowDialog()==true&&editor.Result is {} plan){var updated=row with{Drops=plan};draft[draft.IndexOf(row)]=updated;Update();equipment.SelectKey(updated);feedback.Text="Drop locations saved in the new copy draft. Review & save membership persists them.";}});return;}if(!CanOpenEditor())return;await Run(async()=>{var editor=new DropLocationWindow(row.Item,persist:true){Owner=this};editor.ShowDialog();if(editor.Saved){Saved=true;await LoadSelected();}});}
}
